/**
 * Scenario registry. Every scenario is addressable by id, and generated ones are rebuilt
 * deterministically from their id, so a phone remote only has to send an id string.
 *
 *   fixture ids        scn-riser-leak, scn-gen-nostart, scn-chiller-trip   (src/domain/fixture.ts)
 *   real-incident ids  real-*   adapted from public post-incident reports, compressed, simulated
 *   random ids         rnd-<seed>  generated by randomScenario(seed)
 *
 * CONTRACT (owned by the engine/scenarios agent; other code only calls these four functions).
 */
import { scenarios as fixtureScenarios } from '../fixture';
import type { Scenario } from '../types';

export interface ScenarioInfo { id: string; name: string; kind: NonNullable<Scenario['kind']>; headline: string; basis: string }

/** Any scenario id → Scenario. Unknown ids fall back to the first fixture scenario. */
export function getScenario(id: string): Scenario {
  return fixtureScenarios.find((s) => s.id === id) ?? fixtureScenarios[0];
}

/** Scenarios a presenter can pick from a list (fixtures + real incidents; not random ones). */
export function listScenarios(): ScenarioInfo[] {
  return fixtureScenarios.map((s) => ({ id: s.id, name: s.name, kind: s.kind ?? 'what-if', headline: s.headline ?? s.name, basis: s.basis }));
}

/** A fresh random-disaster id (the caller sends it through the stage). */
export function randomScenarioId(rand: () => number = Math.random): string {
  return `rnd-${Math.floor(rand() * 1e9).toString(36)}`;
}

export const isRandomScenario = (id: string) => id.startsWith('rnd-');
